# -*- coding: utf-8 -*-
from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject


class RunningSoftwareSlot23B(SchemaObject):
    status = SchemaField(name="status")
    running = SchemaField(name="running")
    mode = SchemaField(name="mode")
    id = SchemaField(name="id")
    version = SchemaField(name="version")
    supported_config_reset_options = SchemaField(name="supportedConfigResetOptions", optional=True)

    def __init__(self, status, running, mode, id, version, supported_config_reset_options=None):
        self.status = status
        self.running = running
        self.mode = mode
        self.id = id
        self.version = version
        self.supported_config_reset_options = supported_config_reset_options

        super(RunningSoftwareSlot23B, self).__init__()


class RunningSofware23B(SchemaObject):
    status = SchemaField(name="status")
    slots = SchemaField(name="slots", many=True, klass=RunningSoftwareSlot23B)
    activation_options = SchemaField(name="activationOptions", optional=True)

    def __init__(self, status, slots, activation_options):
        self.status = status
        self.slots = slots
        self.activation_options = activation_options

        super(RunningSofware23B, self).__init__()
